param([int]$TimeoutMilliseconds=2500)
$ErrorActionPreference="Stop"
$probe='<?xml version="1.0" encoding="UTF-8"?><e:Envelope xmlns:e="http://www.w3.org/2003/05/soap-envelope" xmlns:w="http://schemas.xmlsoap.org/ws/2004/08/addressing" xmlns:d="http://schemas.xmlsoap.org/ws/2005/04/discovery" xmlns:dn="http://www.onvif.org/ver10/network/wsdl"><e:Header><w:MessageID>uuid:'+[Guid]::NewGuid().ToString()+'</w:MessageID><w:To>urn:schemas-xmlsoap-org:ws:2005:04:discovery</w:To><w:Action>http://schemas.xmlsoap.org/ws/2005/04/discovery/Probe</w:Action></e:Header><e:Body><d:Probe><d:Types>dn:NetworkVideoTransmitter</d:Types></d:Probe></e:Body></e:Envelope>'
$udp=New-Object Net.Sockets.UdpClient(0);$udp.Client.ReceiveTimeout=250;$destination=New-Object Net.IPEndPoint([Net.IPAddress]::Parse("239.255.255.250"),3702);$bytes=[Text.Encoding]::UTF8.GetBytes($probe);[void]$udp.Send($bytes,$bytes.Length,$destination)
$seen=@{};$until=[DateTime]::UtcNow.AddMilliseconds($TimeoutMilliseconds)
try{while([DateTime]::UtcNow -lt $until){$remote=New-Object Net.IPEndPoint([Net.IPAddress]::Any,0);try{$response=$udp.Receive([ref]$remote);$xml=[Text.Encoding]::UTF8.GetString($response);$xaddr=if($xml -match '<(?:\w+:)?XAddrs[^>]*>([^<]+)'){($matches[1] -split '\s+')[0]}else{"http://$($remote.Address)/onvif/device_service"};if(!$seen.ContainsKey($xaddr)){$seen[$xaddr]=$true;[PSCustomObject]@{address=$remote.Address.ToString();xaddr=$xaddr;endpoint=([Uri]$xaddr).GetLeftPart([UriPartial]::Authority)}}}catch [Net.Sockets.SocketException]{}}}finally{$udp.Dispose()}
